    /// <summary>
    /// Whether a mounted stream has this path. Only new files count, not replaced ones. (Client only.)
    /// </summary>
    /// <param name="path">A game path, for example 'objects/kcds/myres/chair.cgf'.</param>
    /// <returns>boolean</returns>
    public static bool Has(object? path) => Sdk.Call<bool>("core", "Assets", "has", path);
}

/// <summary>
/// The SDK's events by name, for <c>Events.On(EventNames.PlayerReady, (Player player) => ...)</c>.
/// A handler's parameters take the event's arguments in order, converted to their types.
/// </summary>
public static class EventNames
{
    /// <summary>
    /// Client only. The HUD's hints changed: one appeared or went, its text changed, it was greyed out,
    /// or a hold ring moved. ActionHint.shown() reads the new set. (Client only.)
    /// </summary>
    public const string ActionHintsChanged = "actionHintsChanged";

    /// <summary>
    /// A player, horse or NPC entered an area, by its shape, in any dimension. The area is the level's,
    /// such as a house, interior, private ground or settlement, or a resource's. It also fires when an
    /// area is created, moved or enabled around a body. Arguments: (area, entity, matchingDimension).
    /// (Server only.)
    /// </summary>
    public const string AreaEnter = "areaEnter";

    /// <summary>
    /// A player, horse or NPC left an area, or the area was destroyed or disabled around it, or the
    /// server's map changed. Arguments: (area, entity, matchingDimension). (Server only.)
    /// </summary>
    public const string AreaExit = "areaExit";

    /// <summary>
    /// A book closed. Arguments: (id, reason). (Client only.)
    /// </summary>
    public const string BookClosed = "bookClosed";

    /// <summary>
    /// A Book opened in this player's game. Arguments: (id). (Client only.)
    /// </summary>
    public const string BookOpened = "bookOpened";

    /// <summary>
    /// The text in an open book changed. Arguments: (id, text, reason). (Client only.)
    /// </summary>
    public const string BookTextChanged = "bookTextChanged";

    /// <summary>
    /// The player stopped writing in a book. Arguments: (id, text). (Client only.)
    /// </summary>
    public const string BookWritingEnded = "bookWritingEnded";

    /// <summary>
    /// Client only. A Camera.playPath reached its last key; the view holds there until Camera.endShot.
    /// (Client only.)
    /// </summary>
    public const string CameraPathFinished = "cameraPathFinished";

    /// <summary>
    /// A Camera.startShot ended by itself. The server's handler gets (player, reason), and the player's
    /// game gets (reason). Arguments: (player, reason).
    /// </summary>
    public const string CameraShotEnded = "cameraShotEnded";

    /// <summary>
    /// A cart is being removed, with everyone on it let off first. Arguments: (cart). (Server only.)
    /// </summary>
    public const string CartDestroy = "cartDestroy";

    /// <summary>
    /// A player took a seat on a cart. Arguments: (cart, player, seat). (Server only.)
    /// </summary>
    public const string CartEnter = "cartEnter";

    /// <summary>
    /// A player is about to take a seat on a cart. Return false to refuse. Arguments: (cart, player,
    /// seat). (Server only.)
    /// </summary>
    public const string CartEntering = "cartEntering";

    /// <summary>
    /// A player left a cart's seat. Arguments: (cart, player, seat). (Server only.)
    /// </summary>
    public const string CartExit = "cartExit";

    /// <summary>
    /// A cart or wagon was spawned. Arguments: (cart). (Server only.)
    /// </summary>
    public const string CartSpawn = "cartSpawn";

    /// <summary>
    /// The character creator's figure shows another look: a choice in its panel, a random or reset
    /// look, or CharacterCreator.preview. An editor of your own follows it to show what is chosen.
    /// Arguments: (appearance). (Client only.)
    /// </summary>
    public const string CharacterCreatorChanged = "characterCreatorChanged";

    /// <summary>
    /// The character creator closed. Arguments: (appearance, reason). (Client only.)
    /// </summary>
    public const string CharacterCreatorClosed = "characterCreatorClosed";

    /// <summary>
    /// The player pressed the chat key (T) while a resource hid the game's chat with
    /// `Chat.setUIVisible(false)`. Nothing opened; open your own chat window here. The game still gets
    /// the key. (Client only.)
    /// </summary>
    public const string ChatKey = "chatKey";

    /// <summary>
    /// A chat message arrived in this player's game. Arguments: (message). (Client only.)
    /// </summary>
    public const string ChatMessage = "chatMessage";

    /// <summary>
    /// Someone typed a command in the server console that the server does not handle itself. Arguments:
    /// (command, parts). (Server only.)
    /// </summary>
    public const string ConsoleCommand = "consoleCommand";

    /// <summary>
    /// A craft gave its product. Arguments: (player, details). (Server only.)
    /// </summary>
    public const string CraftingCompleted = "craftingCompleted";

    /// <summary>
    /// A craft is about to give its product. Return false to refuse, and the product is taken back.
    /// Arguments: (player, proposal). (Server only.)
    /// </summary>
    public const string CraftingCompleting = "craftingCompleting";

    /// <summary>
    /// A crafting session ended: 'success', 'failed' or 'cancelled'. Arguments: (player, details).
    /// (Server only.)
    /// </summary>
    public const string CraftingEnded = "craftingEnded";

    /// <summary>
    /// A player learned a custom recipe. Arguments: (player, details). (Server only.)
    /// </summary>
    public const string CraftingRecipeLearned = "craftingRecipeLearned";

    /// <summary>
    /// An unfinished craft is settling. Call refund() to return all materials still held, and otherwise
    /// the game's rules apply. Arguments: (player, details, refund). (Server only.)
    /// </summary>
    public const string CraftingRefunding = "craftingRefunding";

    /// <summary>
    /// A player started an alchemy batch, a smithing workpiece or a custom recipe. Arguments: (player,
    /// details). (Server only.)
    /// </summary>
    public const string CraftingStarted = "craftingStarted";

    /// <summary>
    /// A player is about to start crafting. Return false to refuse. Arguments: (player, proposal).
    /// (Server only.)
    /// </summary>
    public const string CraftingStarting = "craftingStarting";

    /// <summary>
    /// A player used a Crafting station with more than one recipe, and your resource chooses what they
    /// craft. Arguments: (player, details). (Server only.)
    /// </summary>
    public const string CraftingStationUsed = "craftingStationUsed";

    /// <summary>
    /// The mouse pointer showed or went away in this game: a resource's `Controls.showCursor`, a
    /// focused page or the chat. It comes once for each change, with what `Controls.isCursorVisible()`
    /// now says. Arguments: (visible). (Client only.)
    /// </summary>
    public const string CursorVisibilityChanged = "cursorVisibilityChanged";

    /// <summary>
    /// A player lays their hand face down on the table (their cover key), covered true, or takes it up
    /// again, false. Return false to refuse. Arguments: (deck, player, covered). (Server only.)
    /// </summary>
    public const string DeckCover = "deckCover";

    /// <summary>
    /// A player presses their draw key (when the deck has one, setActions). Return false to refuse;
    /// otherwise one piece flies from the stack into their hand. Arguments: (deck, player). (Server
    /// only.)
    /// </summary>
    public const string DeckDrawRequest = "deckDrawRequest";

    /// <summary>
    /// A player presses their pass key (Space): a pass, a check or a stand, as your game names it with
    /// setActions. Nothing else happens; the rest is yours. Arguments: (deck, player). (Server only.)
    /// </summary>
    public const string DeckPass = "deckPass";

    /// <summary>
    /// A player asks to play pieces of their hand (their play key): the selected ones, else the one
    /// they point at. Return false to refuse; otherwise their right hand throws them onto the deck's
    /// play pile. Your game's rules go here. Arguments: (deck, player, pieces). (Server only.)
    /// </summary>
    public const string DeckPlayRequest = "deckPlayRequest";

    /// <summary>
    /// A player holding pieces of a TabletopDeck selects one (their select key) or lets it back into
    /// the fan. Return false to refuse. Arguments: (deck, player, piece, selected). (Server only.)
    /// </summary>
    public const string DeckSelect = "deckSelect";

    /// <summary>
    /// A player chose an option in a conversation from Dialogue.open. Arguments: (session, player,
    /// option). (Server only.)
    /// </summary>
    public const string DialogueChoice = "dialogueChoice";

    /// <summary>
    /// A conversation ended. Arguments: (session, player, reason). (Server only.)
    /// </summary>
    public const string DialogueClosed = "dialogueClosed";

    /// <summary>
    /// A badge took effect on a throw. Arguments: (event). (Server only.)
    /// </summary>
    public const string DiceBadge = "diceBadge";

    /// <summary>
    /// A dice match ended. Arguments: (match, first, second, winner, reason, firstScore, secondScore).
    /// (Server only.)
    /// </summary>
    public const string DiceMatchEnd = "diceMatchEnd";

    /// <summary>
    /// A dice match began. Arguments: (match, first, second, target). (Server only.)
    /// </summary>
    public const string DiceMatchStart = "diceMatchStart";

    /// <summary>
    /// A dice match is about to begin, for example because a second player sat down at a table where
    /// another waited. Change `options` here to set the match: `targetScore`, names, dice and badges,
    /// as Dice.start and Dice.startAgainstNpc take them. It runs for every match, also one the shipped
    /// dice resource starts. Arguments: (first, second, table, options). (Server only.)
    /// </summary>
    public const string DiceMatchStarting = "diceMatchStarting";

    /// <summary>
    /// A player held dice and continued or passed. Arguments: (event). (Server only.)
    /// </summary>
    public const string DiceMove = "diceMove";

    /// <summary>
    /// Dice were thrown. Arguments: (event). (Server only.)
    /// </summary>
    public const string DiceRoll = "diceRoll";

    /// <summary>
    /// The dice of a throw lie still on the table. It is the same throw as its diceRoll, which comes
