    /// still for half a second, or four seconds after the throw at the latest, so a score panel waits
    /// for it instead of guessing. Arguments: (event). (Server only.)
    /// </summary>
    public const string DiceSettled = "diceSettled";

    /// <summary>
    /// A player used a dice table. Arguments: (player, table, match). (Server only.)
    /// </summary>
    public const string DiceTableUse = "diceTableUse";

    /// <summary>
    /// A turn ended. Arguments: (event). (Server only.)
    /// </summary>
    public const string DiceTurnEnd = "diceTurnEnd";

    /// <summary>
    /// A player's turn began. Arguments: (event). (Server only.)
    /// </summary>
    public const string DiceTurnStart = "diceTurnStart";

    /// <summary>
    /// A dog is being removed. Arguments: (dog). (Server only.)
    /// </summary>
    public const string DogDestroy = "dogDestroy";

    /// <summary>
    /// A dog's mode changed. Arguments: (dog, mode). (Server only.)
    /// </summary>
    public const string DogModeChanged = "dogModeChanged";

    /// <summary>
    /// A dog got a new owner, or none. Arguments: (dog, owner). (Server only.)
    /// </summary>
    public const string DogOwnerChanged = "dogOwnerChanged";

    /// <summary>
    /// A dog was spawned. Arguments: (dog). (Server only.)
    /// </summary>
    public const string DogSpawn = "dogSpawn";

    /// <summary>
    /// The server met a level door for the first time in this run: a player's game in that dimension
