    /// reporting player gets that state before using it. Door.all() lists the doors met so far.
    /// Arguments: (door, player). (Server only.)
    /// </summary>
    public const string DoorDiscovered = "doorDiscovered";

    /// <summary>
    /// A player is about to open, close, unlock or lockpick a door. Return false to refuse. Arguments:
    /// (player, door, action, keySide). (Server only.)
    /// </summary>
    public const string DoorInteract = "doorInteract";

    /// <summary>
    /// A value in an entity's shared state changed. Arguments: (entity, key, value, previous). (Server
    /// only.)
    /// </summary>
    public const string EntityStateChange = "entityStateChange";

    /// <summary>
    /// Client only. The local player's scripted follow started. Arguments: (target). (Client only.)
    /// </summary>
    public const string FollowStarted = "followStarted";

    /// <summary>
    /// Client only. The local player's follow ended. Arguments: (target, reason). (Client only.)
    /// </summary>
    public const string FollowStopped = "followStopped";

    /// <summary>
    /// Client only. The game's frame changed size, because the player switched between window and full
