    /// </summary>
    public const string GameResolutionChanged = "gameResolutionChanged";

    /// <summary>
    /// A gate's bar was put in or taken out. Arguments: (gate, barred). (Server only.)
    /// </summary>
    public const string GateBarChanged = "gateBarChanged";

    /// <summary>
    /// A gate moved to another state. Arguments: (gate, state). (Server only.)
    /// </summary>
    public const string GateChanged = "gateChanged";

    /// <summary>
    /// A player picked a plant and is about to get it. Return false to refuse. Arguments: (player,
    /// proposal). (Server only.)
    /// </summary>
    public const string GatheringHarvest = "gatheringHarvest";

    /// <summary>
    /// A player got what they picked. Arguments: (player, details). (Server only.)
    /// </summary>
    public const string GatheringHarvested = "gatheringHarvested";

    /// <summary>
    /// A player dug out a grave with the game's digging. All games show it open from now on. Arguments:
    /// (player, grave). (Server only.)
    /// </summary>
    public const string GraveDug = "graveDug";

    /// <summary>
    /// A ground item is being removed. Arguments: (stack). (Server only.)
    /// </summary>
    public const string GroundItemDestroy = "groundItemDestroy";

    /// <summary>
    /// A player picked up a ground item. Arguments: (stack, player). (Server only.)
    /// </summary>
    public const string GroundItemPickup = "groundItemPickup";

    /// <summary>
    /// A ground item came to rest where physics laid it. Its position and rotation are that spot on all
    /// clients, and `resting` is true. It fires once per stack, and not for a landed arrow or bolt,
    /// which rests from the start. Arguments: (stack). (Server only.)
    /// </summary>
    public const string GroundItemResting = "groundItemResting";

    /// <summary>
    /// A stack of items appeared on the ground. Arguments: (stack). (Server only.)
    /// </summary>
    public const string GroundItemSpawn = "groundItemSpawn";

    /// <summary>
    /// A horse lost health. Arguments: (horse, attacker, amount, reason). (Server only.)
    /// </summary>
    public const string HorseDamage = "horseDamage";

    /// <summary>
    /// A horse died, and only revive() brings it back. Arguments: (horse, killer, reason). (Server
    /// only.)
    /// </summary>
    public const string HorseDeath = "horseDeath";

    /// <summary>
    /// A horse is being removed. Arguments: (horse). (Server only.)
    /// </summary>
    public const string HorseDestroy = "horseDestroy";

    /// <summary>
    /// A rider left a horse's saddle, for any reason. Arguments: (horse, player). (Server only.)
    /// </summary>
    public const string HorseDismount = "horseDismount";

    /// <summary>
    /// A horse's tack changed on all clients. Arguments: (horse, player, gear). (Server only.)
    /// </summary>
    public const string HorseGearChanged = "horseGearChanged";

    /// <summary>
    /// A horse's owner changed its tack on the inventory screen's Horse tab, before the server takes
    /// it. Return false to refuse, so the horse keeps its gear on all clients and no item moves. It
