    /// </summary>
    public const string HorseGearChanging = "horseGearChanging";

    /// <summary>
    /// A horse finished a moveTo or patrol order. Arguments: (horse, status). (Server only.)
    /// </summary>
    public const string HorseIntentDone = "horseIntentDone";

    /// <summary>
    /// A horse was knocked out, by a lethal blow when spawned with knockOut, or by knockDown(). Nobody
