    /// </summary>
    public const string HorseKnockedOut = "horseKnockedOut";

    /// <summary>
    /// A player sat in a horse's saddle, by themselves or through player.mount. Arguments: (horse,
    /// player). (Server only.)
    /// </summary>
    public const string HorseMount = "horseMount";

    /// <summary>
    /// A player mounts a horse, before the server accepts it. Handlers run synchronously, and returning
    /// false has their client dismount them, with no horseMount or horseDismount. Arguments: (horse,
    /// player). (Server only.)
    /// </summary>
    public const string HorseMounting = "horseMounting";

    /// <summary>
    /// A horse got a new owner, or none. Arguments: (horse, owner). (Server only.)
    /// </summary>
    public const string HorseOwnerChanged = "horseOwnerChanged";

    /// <summary>
    /// A dead horse was revived. Arguments: (horse). (Server only.)
    /// </summary>
    public const string HorseRevive = "horseRevive";

    /// <summary>
    /// A horse was spawned. Arguments: (horse). (Server only.)
    /// </summary>
    public const string HorseSpawn = "horseSpawn";

    /// <summary>
    /// A knocked-out horse got up. Arguments: (horse). (Server only.)
    /// </summary>
    public const string HorseWake = "horseWake";

    /// <summary>
    /// Client only. How far the game has loaded, for a server's loading page: stage 'resources',
    /// 'level' or 'ready', with a percentage. See LoadingScreen. Scripts do not run yet during
    /// 'download', which only the page hears. Arguments: (stage, percent). (Client only.)
    /// </summary>
    public const string LoadingProgress = "loadingProgress";

    /// <summary>
    /// Client only: the local player was knocked out (the server hears playerDied).
    /// LocalPlayer.knockedOut is true from now until localPlayerRevived. (Client only.)
    /// </summary>
    public const string LocalPlayerKnockedOut = "localPlayerKnockedOut";

    /// <summary>
    /// Client only: the local player, knocked out, was revived (a resource's revive got them up).
    /// LocalPlayer.knockedOut is false again. (Client only.)
    /// </summary>
    public const string LocalPlayerRevived = "localPlayerRevived";

    /// <summary>
    /// Client only. This player's voice started or stopped going out: they hold the talk key, or voice
