    /// </summary>
    public const string LocalVoiceTransmitting = "localVoiceTransmitting";

    /// <summary>
    /// The player discovered a map location, such as a town or district. It happens only on a server
    /// with revealMap off, since otherwise the whole map starts discovered. Keep the GUID with the
    /// character, and mark it again after the next load. Handler promises are not awaited. Arguments:
    /// (locationId). (Client only.)
    /// </summary>
    public const string LocationDiscovered = "locationDiscovered";

    /// <summary>
    /// The local player closed the map. (Client only.)
    /// </summary>
    public const string MapClosed = "mapClosed";

    /// <summary>
    /// The local player opened the map. (Client only.)
    /// </summary>
    public const string MapOpened = "mapOpened";

    /// <summary>
    /// The local player removed their waypoint. Arguments: (position, mapId). (Client only.)
    /// </summary>
    public const string MapWaypointCleared = "mapWaypointCleared";

    /// <summary>
    /// The local player set or moved their map waypoint. Arguments: (position, mapId, moved). (Client
    /// only.)
    /// </summary>
    public const string MapWaypointSet = "mapWaypointSet";

    /// <summary>
    /// A player walked into a trigger marker. Arguments: (marker, player). (Server only.)
    /// </summary>
    public const string MarkerEnter = "markerEnter";

    /// <summary>
    /// A player left a trigger marker. Arguments: (marker, player). (Server only.)
    /// </summary>
    public const string MarkerExit = "markerExit";

    /// <summary>
    /// A marker was placed. Arguments: (marker). (Server only.)
    /// </summary>
    public const string MarkerPlace = "markerPlace";

    /// <summary>
    /// A marker is being removed. Arguments: (marker). (Server only.)
    /// </summary>
    public const string MarkerRemove = "markerRemove";

    /// <summary>
    /// KCDS silenced one of the local character's remarks, which the game voices as Henry whoever
    /// plays. Hud.setInnerVoice(true) lets them speak. The line is chosen from the remark's pool, as
    /// the game would. Arguments: (text, textKey). (Client only.)
    /// </summary>
    public const string MonologueSuppressed = "monologueSuppressed";

    /// <summary>
    /// The game's Esc menu closed in this game, after `nativeMenuOpened`. (Client only.)
    /// </summary>
    public const string NativeMenuClosed = "nativeMenuClosed";

    /// <summary>
    /// The game's Esc menu opened in this game. It is checked every frame, so it comes the frame the
    /// menu shows. (Client only.)
    /// </summary>
    public const string NativeMenuOpened = "nativeMenuOpened";

    /// <summary>
    /// One of the game's own screens went away in this game (see nativeScreenOpened). Arguments:
    /// (name). (Client only.)
    /// </summary>
    public const string NativeScreenClosed = "nativeScreenClosed";

    /// <summary>
    /// One of the game's own screens opened in this game, such as the inventory (ApseInventoryList),
    /// the map (ApseMap) or the journal (ApseQuestLogList); NativeUI.openScreens lists them. A screen
