    /// </summary>
    public const string SiegeEngineWreck = "siegeEngineWreck";

    /// <summary>
    /// A siege engine fired. Arguments: (engine, attacker, target). (Server only.)
    /// </summary>
    public const string SiegeFire = "siegeFire";

    /// <summary>
    /// A siege engine's shot landed. Arguments: (engine, position, attacker). (Server only.)
    /// </summary>
    public const string SiegeImpact = "siegeImpact";

    /// <summary>
    /// A siege ladder is being removed. Arguments: (ladder). (Server only.)
    /// </summary>
    public const string SiegeLadderDestroy = "siegeLadderDestroy";

    /// <summary>
    /// A ladder was pushed away and fell. Arguments: (ladder, pusher). (Server only.)
    /// </summary>
    public const string SiegeLadderFall = "siegeLadderFall";

    /// <summary>
    /// A ladder was raised against a wall. Arguments: (ladder). (Server only.)
    /// </summary>
    public const string SiegeLadderRaise = "siegeLadderRaise";

    /// <summary>
    /// A siege ladder was spawned. Arguments: (ladder). (Server only.)
    /// </summary>
    public const string SiegeLadderSpawn = "siegeLadderSpawn";

    /// <summary>
    /// A player is about to push away or raise a ladder. Return false to refuse. Arguments: (player,
