    /// </summary>
    public const string SiegeLadderUse = "siegeLadderUse";

    /// <summary>
    /// A player closed a stash. Arguments: (stash, player, reason). (Server only.)
    /// </summary>
    public const string StashClose = "stashClose";

    /// <summary>
    /// A stash is being removed. Arguments: (stash). (Server only.)
    /// </summary>
    public const string StashDestroy = "stashDestroy";

    /// <summary>
    /// A player is about to open a stash. Return false to refuse. Arguments: (player, stash, action).
    /// (Server only.)
    /// </summary>
    public const string StashInteract = "stashInteract";

    /// <summary>
    /// A script changed a stash's contents. Arguments: (stash, player, change). (Server only.)
    /// </summary>
    public const string StashInventoryChanged = "stashInventoryChanged";

    /// <summary>
    /// A player opened a stash. Arguments: (stash, player). (Server only.)
    /// </summary>
    public const string StashOpen = "stashOpen";

    /// <summary>
    /// A stash, meaning a chest, container or searchable body, was created. Arguments: (stash). (Server
    /// only.)
    /// </summary>
    public const string StashSpawn = "stashSpawn";

    /// <summary>
    /// A player unlocked a locked stash. Arguments: (stash, player, method). (Server only.)
    /// </summary>
    public const string StashUnlocked = "stashUnlocked";

    /// <summary>
    /// A thrown stone landed, hurting anyone near. Arguments: (pile, position, player). (Server only.)
    /// </summary>
    public const string StoneImpact = "stoneImpact";

    /// <summary>
    /// A stone pile is being removed. Arguments: (pile). (Server only.)
    /// </summary>
    public const string StonePileDestroy = "stonePileDestroy";

    /// <summary>
    /// A stone pile was spawned. Arguments: (pile). (Server only.)
    /// </summary>
    public const string StonePileSpawn = "stonePileSpawn";

    /// <summary>
    /// A player threw a stone from a pile. Arguments: (player, pile). (Server only.)
    /// </summary>
    public const string StonePileThrow = "stonePileThrow";

    /// <summary>
    /// Client only. KCDS stopped a quest's story cutscene playing on this machine. The player stays in
    /// control, the world clock runs on, and the quest continues as if it had played.
    /// Hud.setCutscenes(true) lets them play. Arguments: (cutscene). (Client only.)
    /// </summary>
    public const string StoryCutsceneSuppressed = "storyCutsceneSuppressed";

    /// <summary>
    /// A seated player clicked a cell (whose turn it is, while a game is on), before the table picks or
    /// moves a piece. Return false to take the click yourself, as a game that places pieces does.
    /// Arguments: (table, player, cell). (Server only.)
    /// </summary>
    public const string TabletopCellClick = "tabletopCellClick";

    /// <summary>
    /// A game ended (table.finish, a forfeit or the table's removal). The winner has taken the pot.
    /// Arguments: (table, winner, reason). (Server only.)
    /// </summary>
    public const string TabletopEnd = "tabletopEnd";

    /// <summary>
    /// A player left a game in play and lost it. With one player left, the game then ends with them as
    /// the winner. Arguments: (table, player, seat, reason). (Server only.)
    /// </summary>
    public const string TabletopForfeit = "tabletopForfeit";

    /// <summary>
    /// A player left a Tabletop's seat: 'stood' (the hint or table.stand), 'disconnect' or 'removed'
    /// (the table went). Arguments: (table, player, seat, reason). (Server only.)
    /// </summary>
    public const string TabletopLeave = "tabletopLeave";

    /// <summary>
    /// A seated player asks to move their picked piece to a cell. Return false to refuse; otherwise the
    /// piece hops there. Passing the turn is yours (table.nextTurn). Arguments: (table, player, piece,
    /// cell). (Server only.)
    /// </summary>
    public const string TabletopMoveRequest = "tabletopMoveRequest";

    /// <summary>
    /// A seated player picked a piece in their game (whose turn it is, while a game is on). Return
    /// false to refuse; otherwise the table marks it for them. Arguments: (table, player, piece).
    /// (Server only.)
    /// </summary>
    public const string TabletopPieceSelect = "tabletopPieceSelect";

    /// <summary>
    /// A player sat down at a Tabletop: the moment to start a game once every seat is taken. Arguments:
    /// (table, player, seat). (Server only.)
    /// </summary>
    public const string TabletopSeated = "tabletopSeated";

    /// <summary>
    /// A player is about to sit at a Tabletop, by their request or table.sit. Return false to refuse.
    /// Arguments: (table, player, seat). (Server only.)
    /// </summary>
    public const string TabletopSit = "tabletopSit";

    /// <summary>
    /// A game started at a Tabletop (table.start). Arguments: (table). (Server only.)
    /// </summary>
    public const string TabletopStart = "tabletopStart";

    /// <summary>
    /// The turn went to a seat. Arguments: (table, seat, player). (Server only.)
    /// </summary>
    public const string TabletopTurn = "tabletopTurn";

    /// <summary>
    /// A turn's time (turnSeconds) ran out. Return false to keep the turn for another while; otherwise
    /// it passes. Arguments: (table, seat, player). (Server only.)
    /// </summary>
    public const string TabletopTurnTimeout = "tabletopTurnTimeout";

    /// <summary>
    /// A trade ended. Arguments: (seller, player, reason). (Server only.)
    /// </summary>
    public const string TradeClosed = "tradeClosed";

    /// <summary>
    /// A basket went through, and both inventories changed. Arguments: (seller, buyer, boughtLines,
    /// soldLines, balance). (Server only.)
    /// </summary>
    public const string TradeDone = "tradeDone";

    /// <summary>
    /// The buyer confirmed a basket. Return false to refuse. Arguments: (seller, buyer, boughtLines,
    /// soldLines, balance). (Server only.)
    /// </summary>
    public const string TradeItem = "tradeItem";

    /// <summary>
    /// A trade between two players is about to open. Return false to refuse. Arguments: (seller,
    /// buyer). (Server only.)
    /// </summary>
    public const string TradeOpen = "tradeOpen";

    /// <summary>
    /// Client only. Any player's counted axe blow on a standing tree in this dimension. Handler
    /// promises are not awaited. Arguments: (tree, blow). (Client only.)
    /// </summary>
    public const string TreeChop = "treeChop";

    /// <summary>
    /// Client only. A tree in this dimension starts to fall, for `fall.seconds` along `fall.direction`,
    /// a good moment for a sound or dust. Handler promises are not awaited. Arguments: (tree, fall).
    /// (Client only.)
    /// </summary>
    public const string TreeFalling = "treeFalling";

    /// <summary>
    /// A felled trunk came to rest, and lies as a static prop to be cut. See Trees. It fires on the
    /// server and, for players of its dimension, in client scripts. Arguments: (tree).
    /// </summary>
    public const string TreeFelled = "treeFelled";

    /// <summary>
    /// A felled or cut tree is about to grow back, with its time up and nobody close. Return false to
    /// delay it by a minute. Arguments: (tree). (Server only.)
    /// </summary>
    public const string TreeRegrow = "treeRegrow";

    /// <summary>
    /// A felled tree stands again as in the level. See Trees. It fires on the server and, for players
    /// of its dimension, in client scripts. Arguments: (tree).
    /// </summary>
    public const string TreeRegrown = "treeRegrown";

    /// <summary>
    /// Client only. A felled trunk in this dimension was cut into items. Handler promises are not
    /// awaited. Arguments: (tree, items). (Client only.)
    /// </summary>
    public const string TrunkCut = "trunkCut";

    /// <summary>
    /// A tutorial hint in the corner of the screen closed. Arguments: (id, reason). (Client only.)
    /// </summary>
    public const string TutorialHintClosed = "tutorialHintClosed";

    /// <summary>
    /// A shop screen closed. The server's handler gets (vendorId, player, reason), and the player's
    /// game gets (session, reason). Arguments: (vendor, player, reason).
    /// </summary>
    public const string VendorClosed = "vendorClosed";

    /// <summary>
    /// A player offered a price in the haggle of a vendor created with `haggle` (the game's own haggle
    /// with the trader). Prices are what the player pays, in money units; negative: what the vendor
    /// pays. Return true or { accept: true } to take the offer, { counter: price, mood? } to ask
    /// another price (mood 0 calm to 1 about to leave), false or { refuse: true } to haggle no more in
    /// this session, or nothing to leave the offer to the next handler and then to the vendor's own
    /// rule. The game shows the answer: the trader's reply, the new price and the mood on the haggle
    /// panel. A counter at or below the offer takes the offer. Arguments: (vendorId, player, basket,
    /// offered). (Server only.)
    /// </summary>
    public const string VendorHaggle = "vendorHaggle";

    /// <summary>
    /// A server vendor's shop screen opened in this player's game. Arguments: (session, npc). (Client
    /// only.)
    /// </summary>
    public const string VendorOpened = "vendorOpened";

    /// <summary>
    /// A player traded with a vendor: the server settled their basket. Each line of `bought` and `sold`
    /// is { item, name, amount, price, metadata }: the item's class id and name, the units, the
    /// vendor's price of one unit, and the item's metadata (quality, health). Arguments: (vendorId,
    /// player, bought, sold, balance, haggled). (Server only.)
    /// </summary>
    public const string VendorTrade = "vendorTrade";

    /// <summary>
    /// A visual effect is being removed. Arguments: (vfx). (Server only.)
    /// </summary>
    public const string VfxDestroy = "vfxDestroy";

    /// <summary>
    /// A visual effect was spawned. Arguments: (vfx). (Server only.)
    /// </summary>
    public const string VfxSpawn = "vfxSpawn";

    /// <summary>
    /// A player started or stopped talking in voice chat. Arguments: (player, talking). (Server only.)
    /// </summary>
    public const string VoiceTalkingChanged = "voiceTalkingChanged";

    /// <summary>
    /// A player asked to talk in another tier. Return false to refuse. Arguments: (player, tier).
    /// (Server only.)
    /// </summary>
    public const string VoiceTierRequest = "voiceTierRequest";

    /// <summary>
    /// The local player's weapon struck the world and not a character, such as a tree, wall, rock, prop
    /// or the ground. It fires once per object per attack, on first contact, and not again while the
    /// blade stays against it. Unarmed attacks never fire it, and hits on players, NPCs and animals are
    /// for playerHit and the damage events. The server's event is playerWeaponHit. Handler promises are
    /// not awaited. Arguments: (hit). (Client only.)
    /// </summary>
    public const string WeaponHit = "weaponHit";

    /// <summary>
    /// The world's clock reached a new day. Arguments: (day). (Server only.)
    /// </summary>
    public const string WorldDayChange = "worldDayChange";

    /// <summary>
    /// A player is about to pick up an item the level placed. Return false to refuse. Arguments:
    /// (player, item). (Server only.)
    /// </summary>
    public const string WorldItemPickup = "worldItemPickup";

    /// <summary>
    /// All world resources, the level edits and their exports, have loaded. (Server only.)
    /// </summary>
    public const string WorldResourcesReady = "worldResourcesReady";

    /// <summary>
    /// World.setWeather started changing the weather. Arguments: (preset, previous, seconds). (Server
    /// only.)
    /// </summary>
    public const string WorldWeatherChange = "worldWeatherChange";
}
